import type { Command } from '@commander-js/extra-typings';
import type { CommandServices } from '@wix/cli-command-contract';
import { createCommandTransaction } from '@wix/cli-panorama';
import { reportCommandStartEvent } from '@wix/cli-telemetry';

export async function runCommand(
  command: Command<unknown[]>,
  services: CommandServices,
  cliVersion: string,
  commandFn: () => Promise<void>,
  msid?: string
) {
  const commandStatus = reportCommandStartEvent({
    biLogger: services.biLogger,
    cliVersion,
    command,
    flow: null,
    msid,
  });
  const transaction = createCommandTransaction(services.panorama, command);

  try {
    transaction.start();
    // Every account command requires account-level login. The check lives here
    // rather than in a `preAction` hook on `account` so that a command rejected
    // for not being logged in still reports both BI events — a hook throws
    // before the action runs, which made those attempts invisible.
    await assertLoggedInToAccount();
    await commandFn();
    transaction.finish();
    commandStatus.succeed();
  } catch (error) {
    commandStatus.failed(error);
    throw error;
  }
}

async function assertLoggedInToAccount() {
  const { isLoggedInToAccount } = await import('@wix/cli-auth');
  const { CliError, CliErrorCode } = await import('@wix/cli-error');

  if (!(await isLoggedInToAccount())) {
    throw new CliError({ cause: null, code: CliErrorCode.LoginRequired() });
  }
}
